/* ═══════ Add Section Panel (Wix-style two-column, draggable) ═══════ */
function AddSectionPanel() {
    const addSection = useEditorStore(s => s.addSection)
    const startDrag = useEditorStore(s => s.startDrag)
    const [activeCat, setActiveCat] = useState<string>(SECTION_CATEGORIES[0])

    const filteredTemplates = SECTION_TEMPLATES.filter(t => t.category === activeCat)

    const handleClick = (tmpl: SectionTemplate) => {
        const sec = createSectionFromTemplate(tmpl.id)
        if (sec) addSection(sec)
    }

    const handlePointerDown = (e: React.PointerEvent, tmpl: SectionTemplate) => {
        // Only start drag on left mouse button
        if (e.button !== 0) return
        e.preventDefault()
        startDrag('catalog', { templateId: tmpl.id })
    }

    return (
        <div className="ke-as-layout">
            <div className="ke-as-cats">
                {SECTION_CATEGORIES.map(cat => (
                    <div key={cat} className={`ke-as-cat${activeCat === cat ? ' active' : ''}`} onClick={() => setActiveCat(cat)}>
                        {cat}
                    </div>
                ))}
            </div>
            <div className="ke-as-content">
                <div style={{ fontSize: '11px', fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '12px' }}>{activeCat}</div>
                <div className="ke-as-grid">
                    {filteredTemplates.map(tmpl => (
                        <div
                            key={tmpl.id}
                            className="ke-as-card"
                            onClick={() => handleClick(tmpl)}
                            onPointerDown={e => handlePointerDown(e, tmpl)}
                            style={{ touchAction: 'none' }}
                        >
                            <div className="ke-as-card-icon">{tmpl.icon}</div>
                            <div className="ke-as-card-info">
                                <div className="ke-as-card-name">{tmpl.name}</div>
                                <div className="ke-as-card-desc">{tmpl.description}</div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}

