/* ═══════ Layers Panel ═══════ */
function LayersPanel() {
    const pages = useEditorStore(s => s.pages)
    const activePageId = useEditorStore(s => s.activePageId)
    const selectedSectionId = useEditorStore(s => s.selectedSectionId)
    const selectSection = useEditorStore(s => s.selectSection)
    const toggleSectionVisibility = useEditorStore(s => s.toggleSectionVisibility)
    const moveSection = useEditorStore(s => s.moveSection)

    const sections = pages.find(p => p.id === activePageId)?.sections ?? []

    return (
        <div>
            <div style={{ padding: '12px 16px 0', fontSize: '11px', color: '#94a3b8', fontWeight: 600 }}>{sections.length} bölüm</div>
            <div className="ke-layer-list">
                {sections.map((sec, idx) => (
                    <div
                        key={sec.instanceId}
                        className={`ke-layer-item${selectedSectionId === sec.instanceId ? ' selected' : ''}${!sec.visible ? ' hidden' : ''}`}
                        onClick={() => selectSection(sec.instanceId)}
                    >
                        <div className="ke-layer-grip">
                            <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor"><circle cx="4" cy="3" r="1"/><circle cx="8" cy="3" r="1"/><circle cx="4" cy="6" r="1"/><circle cx="8" cy="6" r="1"/><circle cx="4" cy="9" r="1"/><circle cx="8" cy="9" r="1"/></svg>
                        </div>
                        <span className="ke-layer-icon">{sec.icon}</span>
                        <span className="ke-layer-name">{sec.name}</span>
                        <button className="ke-layer-vis" onClick={e => { e.stopPropagation(); toggleSectionVisibility(sec.instanceId) }} title={sec.visible ? 'Gizle' : 'Göster'}>
                            {sec.visible ? (
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                            ) : (
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19M1 1l22 22"/></svg>
                            )}
                        </button>
                    </div>
                ))}
            </div>
        </div>
    )
}

